<?php
namespace App\Services\Payments;
use App\Contracts\PaymentGatewayInterface; use App\Models\MidtransTransaction; use App\Models\PaymentInvoice; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
final class LocalPaymentService { public function __construct(private readonly PaymentGatewayInterface $gateway){} public function create(PaymentInvoice $invoice,int $userId):MidtransTransaction{if($invoice->legacy_invoice_id!==null||(int)$invoice->getKey()===837)throw ValidationException::withMessages(['invoice'=>'Invoice legacy/quarantine tidak dapat diproses.']);if((int)$invoice->user_id!==$userId||$invoice->status!==PaymentInvoice::STATUS_UNPAID)throw ValidationException::withMessages(['invoice'=>'Invoice tidak tersedia.']);if((float)$invoice->amount<=0)throw ValidationException::withMessages(['amount'=>'Nominal harus lebih besar dari nol.']);$existing=MidtransTransaction::query()->where('payment_invoice_id',$invoice->getKey())->whereIn('transaction_status',['pending','paid'])->first();if($existing)return $existing;$id='LOCAL-'.Str::upper(Str::ulid()->toBase32());$g=$this->gateway->create($invoice,$id);return MidtransTransaction::query()->create(['payment_invoice_id'=>$invoice->getKey(),'user_id'=>$userId,'order_id'=>$g['order_id'],'idempotency_key'=>$g['order_id'],'gross_amount'=>$g['gross_amount'],'transaction_status'=>'pending','source'=>'local_mock','raw_status_snapshot'=>['source'=>'local_mock','status'=>'pending']]);} public function callback(string $orderId,string $status,?string $transactionId=null):MidtransTransaction{if(!in_array($status,['pending','paid','failed','expired','cancelled'],true))throw ValidationException::withMessages(['status'=>'Status tidak valid.']);$t=MidtransTransaction::query()->where('order_id',$orderId)->lockForUpdate()->firstOrFail();if($t->transaction_status==='paid'&&$status!=='paid')return $t;$p=$this->gateway->callback($orderId,$status,$transactionId);$t->fill(['transaction_status'=>$status,'transaction_id'=>$p['transaction_id']??$t->transaction_id,'raw_status_snapshot'=>['source'=>'local_mock','status'=>$status]])->save();return $t->refresh();} }
